class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


import heapq


def sortNearlySorted(nums, k):
    cur = build(nums)
    dummy = ListNode()
    tail = dummy
    heap = []
    uid = 0
    while cur:
        heapq.heappush(heap, (cur.val, uid, cur))
        uid += 1
        cur = cur.next
        if len(heap) > k:
            node = heapq.heappop(heap)[2]
            tail.next = node
            tail = node
    while heap:
        node = heapq.heappop(heap)[2]
        tail.next = node
        tail = node
    tail.next = None
    return dump(dummy.next)
